"""Append 351 true/false items to trueorfalse/statements.json (tof_0204 to tof_0554)."""
import json
from pathlib import Path

FILE = Path(__file__).parent / "trueorfalse" / "statements.json"
data = json.loads(FILE.read_text(encoding="utf-8"))

new_items = [
{"id":"tof_0204","statement":"A day on Venus is longer than a year on Venus.","verdict":"TRUE","explanation":"Venus rotates so slowly that it takes 243 Earth days to complete one rotation, but only 225 Earth days to orbit the Sun.","category":"space","hook":"True or False?"},
{"id":"tof_0205","statement":"Humans share 50% of their DNA with bananas.","verdict":"TRUE","explanation":"About half of human genes have counterparts in bananas. These are ancient genes controlling basic cellular functions shared by all living things.","category":"science","hook":"You're basically a banana"},
{"id":"tof_0206","statement":"The Eiffel Tower grows taller in summer.","verdict":"TRUE","explanation":"Thermal expansion causes the iron structure to grow by up to 15 cm on hot days as the metal expands in the heat.","category":"science","hook":"True or False?"},
{"id":"tof_0207","statement":"Napoleon Bonaparte was unusually short for his time.","verdict":"FALSE","explanation":"Napoleon was around 5'7\" (170 cm), average height for a Frenchman of his era. The 'short' myth came from a British propaganda cartoon and confusion over French vs English measurement units.","category":"history","hook":"The most famous height myth"},
{"id":"tof_0208","statement":"Goldfish have a memory span of only 3 seconds.","verdict":"FALSE","explanation":"Goldfish can remember things for months. They can be trained to navigate mazes and respond to signals, demonstrating memories lasting well over a year.","category":"animals","hook":"You've heard this one"},
{"id":"tof_0209","statement":"Lightning never strikes the same place twice.","verdict":"FALSE","explanation":"Lightning frequently strikes the same location multiple times. The Empire State Building is struck by lightning around 25 times per year.","category":"science","hook":"The oldest myth in the book"},
{"id":"tof_0210","statement":"There are more trees on Earth than stars in the Milky Way.","verdict":"TRUE","explanation":"Earth has approximately 3 trillion trees. The Milky Way contains an estimated 100–400 billion stars — meaning trees outnumber stars in our galaxy by roughly 7 to 1.","category":"nature","hook":"True or False?"},
{"id":"tof_0211","statement":"Humans only use 10% of their brains.","verdict":"FALSE","explanation":"Brain imaging shows that virtually all areas of the brain are active at some point. Even during sleep, more than 10% of the brain is in use.","category":"science","hook":"Schools still teach this"},
{"id":"tof_0212","statement":"The Great Wall of China is the only man-made structure visible from space.","verdict":"FALSE","explanation":"The Great Wall is far too narrow to see from low Earth orbit with the naked eye. Even Chinese astronaut Yang Liwei confirmed he could not see it.","category":"geography","hook":"Taught in schools worldwide"},
{"id":"tof_0213","statement":"Cleopatra lived closer in time to the Moon landing than to the building of the Great Pyramid.","verdict":"TRUE","explanation":"The Great Pyramid was built around 2560 BC. Cleopatra lived around 30 BC. The Moon landing was 1969 AD. Cleopatra is separated from the pyramid by 2,530 years but from the Moon landing by only 1,999 years.","category":"history","hook":"This will break your brain"},
{"id":"tof_0214","statement":"Waking a sleepwalker is dangerous and can harm them.","verdict":"FALSE","explanation":"Waking a sleepwalker is not harmful. It may disorient them briefly, but is far safer than letting them continue, as sleepwalkers can injure themselves.","category":"science","hook":"True or False?"},
{"id":"tof_0215","statement":"The sun is yellow.","verdict":"FALSE","explanation":"The sun emits white light. It appears yellow or orange from Earth due to atmospheric scattering of shorter blue wavelengths. Astronauts in space see it as brilliant white.","category":"space","hook":"You look at it every day"},
{"id":"tof_0216","statement":"Elephants are the only animals that cannot jump.","verdict":"FALSE","explanation":"Several animals cannot jump, including sloths, hippos, rhinos, and elephants. Elephants are notable for it but are not unique.","category":"animals","hook":"True or False?"},
{"id":"tof_0217","statement":"Your fingernails continue to grow after you die.","verdict":"FALSE","explanation":"Nail growth requires living cells and hormones. After death, the skin dehydrates and pulls back, making nails appear longer — but they are not actually growing.","category":"science","hook":"A classic horror myth"},
{"id":"tof_0218","statement":"Humans are the only animals that blush.","verdict":"TRUE","explanation":"Blushing as an involuntary emotional response to embarrassment or shame appears to be unique to humans. No other animal has been documented blushing in the same way.","category":"science","hook":"True or False?"},
{"id":"tof_0219","statement":"The Amazon River flows into the Pacific Ocean.","verdict":"FALSE","explanation":"The Amazon River flows eastward across South America and empties into the Atlantic Ocean off the coast of Brazil.","category":"geography","hook":"Do you know your rivers?"},
{"id":"tof_0220","statement":"A group of flamingos is called a flamboyance.","verdict":"TRUE","explanation":"The collective noun for flamingos is indeed a flamboyance — fitting for a bird known for its dramatic pink colour and display behaviour.","category":"animals","hook":"True or False?"},
{"id":"tof_0221","statement":"Hot water freezes faster than cold water.","verdict":"TRUE","explanation":"Known as the Mpemba effect, hot water can under certain conditions freeze faster than cold water, though scientists still debate the exact mechanisms.","category":"science","hook":"It sounds impossible"},
{"id":"tof_0222","statement":"Chameleons change colour to camouflage themselves.","verdict":"FALSE","explanation":"Chameleons primarily change colour to communicate mood, temperature regulation, and attract mates. Their resting colour is usually already well camouflaged.","category":"animals","hook":"Everyone believes this"},
{"id":"tof_0223","statement":"Bulls are enraged by the colour red.","verdict":"FALSE","explanation":"Bulls are colour-blind to red. They are agitated by the movement of the matador's cape, not its colour. Tests with static red cloths produce no reaction.","category":"animals","hook":"What actually makes a bull charge?"},
{"id":"tof_0224","statement":"Mount Everest is the tallest mountain on Earth.","verdict":"TRUE","explanation":"Measured from sea level, Everest at 8,849 m is the tallest. Note: Mauna Kea is taller from base to summit, and Chimborazo is farthest from Earth's centre, but Everest wins on standard sea-level measurement.","category":"geography","hook":"Or is it?"},
{"id":"tof_0225","statement":"We swallow an average of 8 spiders per year in our sleep.","verdict":"FALSE","explanation":"This is a completely fabricated statistic. Spiders avoid humans due to our vibrations and breathing. There is no evidence of anyone regularly swallowing spiders while asleep.","category":"animals","hook":"The internet's favourite myth"},
{"id":"tof_0226","statement":"The tongue has distinct zones for tasting sweet, salty, sour, and bitter.","verdict":"FALSE","explanation":"The 'tongue map' was debunked decades ago. Taste receptors for all flavours are distributed across the entire tongue.","category":"science","hook":"Taught in schools"},
{"id":"tof_0227","statement":"An octopus has three hearts.","verdict":"TRUE","explanation":"Octopuses have three hearts: two pump blood to the gills, and one pumps it to the rest of the body. They also have blue blood due to copper-based haemocyanin.","category":"animals","hook":"True or False?"},
{"id":"tof_0228","statement":"Glass is a slow-moving liquid.","verdict":"FALSE","explanation":"Old windows are thicker at the bottom due to manufacturing methods, not because glass flowed. Glass is an amorphous solid with no measurable flow at room temperature.","category":"science","hook":"Still taught as fact"},
{"id":"tof_0229","statement":"Bats are blind.","verdict":"FALSE","explanation":"All bat species can see. Many have excellent vision, and fruit bats have particularly sharp eyesight. They use echolocation in addition to — not instead of — their vision.","category":"animals","hook":"True or False?"},
{"id":"tof_0230","statement":"Water drains in opposite directions in the northern and southern hemispheres.","verdict":"FALSE","explanation":"The Coriolis effect is far too weak to affect draining water. The direction water drains depends almost entirely on the shape of the basin, not its hemisphere.","category":"science","hook":"What about the Coriolis effect?"},
{"id":"tof_0231","statement":"Albert Einstein failed mathematics at school.","verdict":"FALSE","explanation":"Einstein excelled at maths and physics. He mastered calculus by age 15. The myth arose from misinterpretation of Swiss school grading where 6 was the top grade, not 1.","category":"history","hook":"True or False?"},
{"id":"tof_0232","statement":"Polar bears have black skin under their white fur.","verdict":"TRUE","explanation":"Polar bear skin is black to absorb heat from the sun. Their fur appears white but is actually transparent — it scatters light to appear white.","category":"animals","hook":"What colour is a polar bear?"},
{"id":"tof_0233","statement":"Humans have more than five senses.","verdict":"TRUE","explanation":"Beyond the classic five, humans have senses including proprioception (body position), thermoception (temperature), nociception (pain), equilibrioception (balance), and more — totalling over 20 recognised senses.","category":"science","hook":"How many senses do you have?"},
{"id":"tof_0234","statement":"The letter 'Q' does not appear in any US state name.","verdict":"TRUE","explanation":"No US state name contains the letter Q. It is one of only two letters missing from US state names — the other is 'B'.","category":"geography","hook":"True or False?"},
{"id":"tof_0235","statement":"A teaspoon of neutron star material would weigh about a billion tonnes.","verdict":"TRUE","explanation":"Neutron stars are so dense that a teaspoon of their material would weigh roughly 10 million tonnes to 1 billion tonnes depending on the star.","category":"space","hook":"The most dense thing in the universe"},
{"id":"tof_0236","statement":"Dogs can only see in black and white.","verdict":"FALSE","explanation":"Dogs have two types of colour receptors compared to humans' three, giving them dichromatic vision. They can see blues and yellows but have difficulty distinguishing red and green.","category":"animals","hook":"True or False?"},
{"id":"tof_0237","statement":"The human body contains more bacterial cells than human cells.","verdict":"TRUE","explanation":"Recent estimates suggest roughly equal numbers or a slight majority of bacterial cells over human cells. Earlier estimates suggested a 10:1 ratio, now revised to approximately 1:1.","category":"science","hook":"Who are you really?"},
{"id":"tof_0238","statement":"Frankenstein is the name of the monster.","verdict":"FALSE","explanation":"Frankenstein is the name of the scientist Victor Frankenstein who created the creature. The creature himself has no name in Mary Shelley's novel.","category":"language","hook":"True or False?"},
{"id":"tof_0239","statement":"Snakes have eyelids.","verdict":"FALSE","explanation":"Snakes have no eyelids. Instead, their eyes are protected by transparent scales called brille or spectacles, which is why snakes always appear to be staring.","category":"animals","hook":"Do snakes blink?"},
{"id":"tof_0240","statement":"The Pacific Ocean is larger than all of Earth's land combined.","verdict":"TRUE","explanation":"The Pacific Ocean covers approximately 165 million square kilometres. All of Earth's land adds up to about 149 million square kilometres — making the Pacific bigger.","category":"geography","hook":"True or False?"},
{"id":"tof_0241","statement":"Cats always land on their feet.","verdict":"FALSE","explanation":"Cats have a righting reflex that helps them orient feet-down during a fall, but this requires enough height and time. Falls from very low heights or onto specific surfaces can still injure or kill them.","category":"animals","hook":"A myth with a grain of truth"},
{"id":"tof_0242","statement":"Humans and dinosaurs never coexisted.","verdict":"TRUE","explanation":"Non-avian dinosaurs went extinct approximately 66 million years ago. Anatomically modern humans evolved only around 300,000 years ago — a gap of over 65 million years.","category":"history","hook":"Or did they?"},
{"id":"tof_0243","statement":"You lose most of your body heat through your head.","verdict":"FALSE","explanation":"Heat loss is roughly proportional to skin surface area. The head loses about 10% of body heat — the same as any other body part of similar size. The myth arose from outdated military cold-weather studies.","category":"science","hook":"Wear a hat they said"},
{"id":"tof_0244","statement":"There are more possible iterations of a shuffled deck of cards than atoms on Earth.","verdict":"TRUE","explanation":"The number of ways to arrange a 52-card deck is 52! — approximately 8 × 10^67. The number of atoms on Earth is estimated at around 10^50. The shuffles vastly exceed the atoms.","category":"science","hook":"Truly mind-bending"},
{"id":"tof_0245","statement":"Sharks are mammals.","verdict":"FALSE","explanation":"Sharks are fish — specifically cartilaginous fish (class Chondrichthyes). They breathe through gills, are cold-blooded, and lay eggs or give live birth but are not mammals.","category":"animals","hook":"True or False?"},
{"id":"tof_0246","statement":"The shortest war in history lasted 38 minutes.","verdict":"TRUE","explanation":"The Anglo-Zanzibar War of 1896 lasted between 38 and 45 minutes, making it the shortest war in recorded history. Zanzibar surrendered after the sultan's palace was bombarded.","category":"history","hook":"How short can a war be?"},
{"id":"tof_0247","statement":"Humans have been to the Moon more recently than they invented the mobile phone.","verdict":"FALSE","explanation":"The last Moon landing was Apollo 17 in December 1972. The first mobile phone call was made by Martin Cooper in April 1973 — four months after the last Moon landing.","category":"history","hook":"Check the timeline"},
{"id":"tof_0248","statement":"An apple a day keeps the doctor away is scientifically proven.","verdict":"FALSE","explanation":"There is no strong scientific evidence that eating an apple daily reduces doctor visits. It is a folk saying from 19th century Wales: 'Eat an apple on going to bed and you'll keep the doctor from earning his bread.'","category":"food","hook":"True or False?"},
{"id":"tof_0249","statement":"Oxygen is the most abundant element in Earth's atmosphere.","verdict":"FALSE","explanation":"Nitrogen makes up about 78% of Earth's atmosphere. Oxygen is second at about 21%. Many people assume the air is mostly oxygen because we breathe it.","category":"science","hook":"What's in the air?"},
{"id":"tof_0250","statement":"A jiffy is an actual unit of time.","verdict":"TRUE","explanation":"In computing, a jiffy is 1/100th of a second. In physics, it refers to the time it takes light to travel one femtometre (about 3 × 10^-26 seconds).","category":"science","hook":"In a jiffy"},
{"id":"tof_0251","statement":"Antibiotics work against viral infections like the flu.","verdict":"FALSE","explanation":"Antibiotics target bacteria. Viruses have completely different biology and are not affected by antibiotics. Taking antibiotics for viral illness is ineffective and contributes to antibiotic resistance.","category":"science","hook":"True or False?"},
{"id":"tof_0252","statement":"The word 'nerd' was first used in a Dr. Seuss book.","verdict":"TRUE","explanation":"The word 'nerd' first appeared in the 1950 Dr. Seuss book 'If I Ran the Zoo.' It was used to describe a fictional creature before being adopted as slang.","category":"language","hook":"Thanks, Dr. Seuss"},
{"id":"tof_0253","statement":"Hawaii is the southernmost US state.","verdict":"FALSE","explanation":"Trick question — it depends on definition. Hawaii is the southernmost US state by mainland position, but the southernmost point of US territory is the Palmyra Atoll. Hawaii's South Point is the southernmost point of the 50 states.","category":"geography","hook":"Actually TRUE — Hawaii is southernmost of the 50 states"},
{"id":"tof_0254","statement":"The average person walks past 36 murderers in their lifetime.","verdict":"FALSE","explanation":"This is a fabricated statistic with no source. It is passed around online as a 'fact' but has no basis in criminology or any credible research.","category":"science","hook":"True or False?"},
{"id":"tof_0255","statement":"Pluto was classified as a planet for 76 years.","verdict":"TRUE","explanation":"Pluto was discovered and classified as the ninth planet in 1930. It was reclassified as a dwarf planet by the International Astronomical Union in 2006 — exactly 76 years later.","category":"space","hook":"Moment of silence for Pluto"},
{"id":"tof_0256","statement":"Crocodiles can't stick out their tongues.","verdict":"TRUE","explanation":"Crocodiles' tongues are attached to the roof of their mouths by a membrane across the entire length, preventing them from extending their tongues outside their mouths.","category":"animals","hook":"True or False?"},
{"id":"tof_0257","statement":"The first computer bug was an actual bug.","verdict":"TRUE","explanation":"In 1947, Grace Hopper's team found a moth stuck in a relay of the Harvard Mark II computer. They taped it into their logbook with the note 'First actual case of bug being found.'","category":"technology","hook":"A literal bug in the system"},
{"id":"tof_0258","statement":"Vikings wore horned helmets.","verdict":"FALSE","explanation":"No evidence of horned Viking helmets has been found. The image comes from a 19th-century costume designer. The one complete Viking helmet ever found has no horns.","category":"history","hook":"True or False?"},
{"id":"tof_0259","statement":"Honey never spoils.","verdict":"TRUE","explanation":"Honey has been found in Egyptian tombs thousands of years old and is still edible. Its low moisture content and acidic pH prevent bacterial and fungal growth.","category":"food","hook":"The oldest food in the world"},
{"id":"tof_0260","statement":"Mount Everest is the closest point on Earth to the Moon.","verdict":"FALSE","explanation":"Because Earth bulges at the equator, the summit of Mount Chimborazo in Ecuador is the farthest point from Earth's centre and closest to the Moon, despite being 2,500m shorter than Everest.","category":"geography","hook":"Which mountain reaches space?"},
{"id":"tof_0261","statement":"Spiders are insects.","verdict":"FALSE","explanation":"Spiders are arachnids, not insects. They have eight legs and two body segments (cephalothorax and abdomen), while insects have six legs and three body segments.","category":"animals","hook":"True or False?"},
{"id":"tof_0262","statement":"The Stanford Prison Experiment is considered a landmark of ethical psychology.","verdict":"FALSE","explanation":"The Stanford Prison Experiment of 1971 is now considered deeply unethical and methodologically flawed. It was stopped early and has been widely criticised for participant abuse and lack of scientific rigour.","category":"science","hook":"Landmark or disaster?"},
{"id":"tof_0263","statement":"Bananas are technically berries, but strawberries are not.","verdict":"TRUE","explanation":"By botanical definition, a berry is a fruit from a single ovary. Bananas qualify. Strawberries are 'accessory fruits' from multiple ovaries — not true berries. Avocados are also technically berries.","category":"food","hook":"True or False?"},
{"id":"tof_0264","statement":"The Statue of Liberty was a gift from France to the USA.","verdict":"TRUE","explanation":"The Statue of Liberty was designed by French sculptor Frédéric Auguste Bartholdi and given to the United States by France in 1886 to celebrate the two nations' shared values.","category":"history","hook":"Who built Lady Liberty?"},
{"id":"tof_0265","statement":"You can see the Milky Way galaxy from Earth with the naked eye.","verdict":"TRUE","explanation":"The glowing band visible across a dark night sky is the Milky Way galaxy viewed from within. In places with minimal light pollution, thousands of individual stars and the galaxy's structure are clearly visible.","category":"space","hook":"True or False?"},
{"id":"tof_0266","statement":"Camels store water in their humps.","verdict":"FALSE","explanation":"Camel humps store fat, not water. The fat provides an energy reserve. Camels conserve water through extremely efficient kidneys and can drink up to 135 litres at once to rehydrate.","category":"animals","hook":"Everyone believes this"},
{"id":"tof_0267","statement":"The world's largest desert is Antarctica.","verdict":"TRUE","explanation":"A desert is defined by low precipitation, not heat or sand. Antarctica receives less than 200mm of precipitation per year, making it the world's largest cold desert at 14.2 million km².","category":"geography","hook":"Largest desert on Earth"},
{"id":"tof_0268","statement":"There are more public libraries in the US than McDonald's restaurants.","verdict":"TRUE","explanation":"The United States has approximately 17,000 public libraries compared to about 14,000 McDonald's locations. Libraries still outnumber the golden arches.","category":"geography","hook":"True or False?"},
{"id":"tof_0269","statement":"Eating carrots improves your night vision.","verdict":"FALSE","explanation":"Carrots contain beta-carotene which the body converts to Vitamin A, needed for eye health. But eating extra carrots won't improve normal vision. The myth was British WWII propaganda to hide their use of radar.","category":"food","hook":"The carrot myth"},
{"id":"tof_0270","statement":"Saturn could float on water.","verdict":"TRUE","explanation":"Saturn has the lowest density of all planets — about 0.687 g/cm³, less than water (1.0 g/cm³). If a large enough ocean existed, Saturn would technically float.","category":"space","hook":"Could a planet float?"},
{"id":"tof_0271","statement":"Taste buds die and are replaced every 10 days.","verdict":"TRUE","explanation":"Taste receptor cells have a lifespan of roughly 10–14 days and are continuously regenerated throughout life, which is why taste perception can recover after damage.","category":"science","hook":"True or False?"},
{"id":"tof_0272","statement":"The original Olympics in ancient Greece included women's events.","verdict":"FALSE","explanation":"Married women were banned from even watching the ancient Olympics. A separate Games called the Heraia was held for women, though it was much smaller.","category":"history","hook":"Women at the ancient Olympics?"},
{"id":"tof_0273","statement":"Blood is blue inside the body.","verdict":"FALSE","explanation":"Blood is always red. Deoxygenated blood is dark red, not blue. Veins appear blue through skin due to how different wavelengths of light penetrate and reflect off tissue.","category":"science","hook":"True or False?"},
{"id":"tof_0274","statement":"The inventor of the telephone never called his mother or wife because they were both deaf.","verdict":"TRUE","explanation":"Alexander Graham Bell's mother and wife were both deaf. Despite inventing the telephone, he had no one close to him to call with it — an extraordinary historical irony.","category":"history","hook":"A tragic irony"},
{"id":"tof_0275","statement":"Humans and chimpanzees share 98.7% of their DNA.","verdict":"TRUE","explanation":"Genome sequencing shows that humans and chimpanzees share approximately 98.7% of their DNA sequence, making chimps our closest living relatives in the animal kingdom.","category":"science","hook":"True or False?"},
{"id":"tof_0276","statement":"A group of crows is called a flock.","verdict":"FALSE","explanation":"A group of crows is called a murder. Other unusual collective nouns include a parliament of owls, a prickle of porcupines, and a crash of rhinos.","category":"animals","hook":"What's a group of crows called?"},
{"id":"tof_0277","statement":"The first commercial flight was in 1914.","verdict":"TRUE","explanation":"The world's first scheduled commercial airline service launched on 1 January 1914 in Florida, USA, operated by the St. Petersburg–Tampa Airboat Line. The flight took 23 minutes.","category":"history","hook":"True or False?"},
{"id":"tof_0278","statement":"Blind people dream in images.","verdict":"TRUE","explanation":"People who were sighted and later became blind often still experience visual imagery in dreams. Those born blind tend to dream using their other senses — sound, touch, smell.","category":"science","hook":"Do blind people see in dreams?"},
{"id":"tof_0279","statement":"The Sahara Desert is always hot.","verdict":"FALSE","explanation":"The Sahara experiences cold winters and can have frost and even snow. Temperatures in January can drop below freezing at night, especially in elevated areas.","category":"geography","hook":"True or False?"},
{"id":"tof_0280","statement":"Humans are the only animals that cry emotional tears.","verdict":"TRUE","explanation":"While other animals produce tears to lubricate eyes, humans are the only animals documented to shed tears specifically in response to emotional states.","category":"science","hook":"Are we alone in our tears?"},
{"id":"tof_0281","statement":"The Wright brothers' first flight was shorter than the wingspan of a 747.","verdict":"TRUE","explanation":"The Wright brothers' first flight at Kitty Hawk in 1903 covered 37 metres. A Boeing 747 has a wingspan of 68 metres — meaning the first flight would fit entirely within the wings.","category":"history","hook":"True or False?"},
{"id":"tof_0282","statement":"Coffee is the second most traded commodity in the world.","verdict":"FALSE","explanation":"Coffee is often cited as second behind oil, but this is incorrect. By value, the most traded commodities include crude oil, refined petroleum, gold, and soybeans. Coffee is significant but not second.","category":"food","hook":"The coffee myth"},
{"id":"tof_0283","statement":"A single bolt of lightning contains enough energy to toast 100,000 slices of bread.","verdict":"TRUE","explanation":"A lightning bolt carries about 1–5 billion joules. A toaster uses around 100,000 joules per slice. The energy in one bolt could theoretically toast 10,000 to 50,000 slices.","category":"science","hook":"True or False?"},
{"id":"tof_0284","statement":"Humans are born with 270 bones but adults have only 206.","verdict":"TRUE","explanation":"Babies are born with around 270–300 separate bones, many of which fuse together during childhood and adolescence. Adults end up with 206 bones.","category":"science","hook":"How many bones do you have?"},
{"id":"tof_0285","statement":"The colour orange is named after the fruit.","verdict":"TRUE","explanation":"The fruit came first. Orange was used as a colour name in English only after the fruit arrived in Europe in the 16th century. Before that, the colour was called 'geoluhread' (yellow-red) in Old English.","category":"language","hook":"True or False?"},
{"id":"tof_0286","statement":"You can tell a tree's age only by cutting it down and counting rings.","verdict":"FALSE","explanation":"Dendrochronologists can core a tree with a thin hollow drill, extract a sample, and count growth rings without cutting the tree down.","category":"nature","hook":"How to age a tree"},
{"id":"tof_0287","statement":"Friday the 13th is statistically more dangerous than other days.","verdict":"FALSE","explanation":"Multiple studies have found no statistically significant increase in accidents, injuries, or emergency room visits on Friday the 13th compared to other Fridays.","category":"science","hook":"True or False?"},
{"id":"tof_0288","statement":"Cows produce more milk when they listen to music.","verdict":"TRUE","explanation":"Research from the University of Leicester found that cows listening to slow music produced more milk than those in silence or hearing fast music. Relaxation appears to aid milk production.","category":"animals","hook":"Music for cows?"},
{"id":"tof_0289","statement":"Water is the most abundant compound on Earth's surface.","verdict":"TRUE","explanation":"About 71% of Earth's surface is covered by water. It is by far the most abundant compound in the oceans, ice caps, rivers, and groundwater systems.","category":"science","hook":"True or False?"},
{"id":"tof_0290","statement":"Humans are taller in the morning than in the evening.","verdict":"TRUE","explanation":"The cartilage discs in your spine compress slightly throughout the day under gravity. You can be up to 1–2 cm taller in the morning after a night of lying horizontal.","category":"science","hook":"Rise and shine, literally"},
{"id":"tof_0291","statement":"A cucumber is a fruit.","verdict":"TRUE","explanation":"Botanically, a cucumber is a fruit because it develops from the flower of a plant and contains seeds. In culinary practice it's treated as a vegetable due to its savoury taste.","category":"food","hook":"True or False?"},
{"id":"tof_0292","statement":"The brain cannot feel pain.","verdict":"TRUE","explanation":"The brain has no pain receptors itself. Brain surgery can be performed on conscious patients. Headaches are caused by pain in surrounding structures like blood vessels, meninges, and muscles.","category":"science","hook":"Can your brain hurt?"},
{"id":"tof_0293","statement":"Isaac Newton discovered gravity when an apple fell on his head.","verdict":"FALSE","explanation":"The apple story is a simplified retelling — possibly exaggerated. Newton reportedly observed an apple falling from a tree in his garden, which prompted his thinking about gravity, but it did not hit him on the head.","category":"history","hook":"True or False?"},
{"id":"tof_0294","statement":"Some metals are liquid at room temperature.","verdict":"TRUE","explanation":"Mercury is the best-known example — a liquid metal at room temperature. Gallium melts at just 29.8°C, meaning it liquefies from the heat of your hand.","category":"science","hook":"Liquid metal?"},
{"id":"tof_0295","statement":"The first Olympic gold medals were solid gold.","verdict":"FALSE","explanation":"The last all-gold medals were awarded at the 1912 Olympics. Modern Olympic gold medals are made of silver plated with at least 6 grams of gold.","category":"sports","hook":"True or False?"},
{"id":"tof_0296","statement":"Penguins propose to their mates with pebbles.","verdict":"TRUE","explanation":"Male Gentoo penguins sift through pebbles to find the best one and present it to a potential mate. If she accepts, she puts it in the nest — and they often mate for life.","category":"animals","hook":"The most romantic animal?"},
{"id":"tof_0297","statement":"The capital of Australia is Sydney.","verdict":"FALSE","explanation":"The capital of Australia is Canberra. It was purpose-built as a compromise capital because Sydney and Melbourne both wanted the title. Canberra became the capital in 1913.","category":"geography","hook":"True or False?"},
{"id":"tof_0298","statement":"Humans share DNA with every living organism on Earth.","verdict":"TRUE","explanation":"All life on Earth shares a common ancestor and uses the same genetic code. Humans share DNA with bacteria, plants, fungi, and every other living thing — just in different amounts.","category":"science","hook":"You're related to everything"},
{"id":"tof_0299","statement":"The first iPhone was released in 2007.","verdict":"TRUE","explanation":"Steve Jobs unveiled the first iPhone on January 9, 2007, and it went on sale on June 29, 2007. It is widely regarded as one of the most significant product launches in technology history.","category":"technology","hook":"True or False?"},
{"id":"tof_0300","statement":"Raindrops are shaped like teardrops.","verdict":"FALSE","explanation":"Small raindrops are nearly spherical. Larger drops become flattened on the bottom like a hamburger bun as they fall, due to air resistance. The teardrop shape is a myth.","category":"science","hook":"What shape is a raindrop?"},
{"id":"tof_0301","statement":"An adult human produces enough saliva in a lifetime to fill two swimming pools.","verdict":"TRUE","explanation":"The human body produces between 0.5 and 1.5 litres of saliva per day. Over a lifetime of 80 years, this totals between 14,600 and 43,800 litres — enough to fill one or two swimming pools.","category":"science","hook":"True or False?"},
{"id":"tof_0302","statement":"Lobsters were considered prison food in colonial America.","verdict":"TRUE","explanation":"Lobsters were so abundant in colonial New England that they were seen as food for the poor, prisoners, and servants. Some servants allegedly negotiated contracts stipulating they would not be fed lobster more than three times a week.","category":"history","hook":"The cheapest food in history"},
{"id":"tof_0303","statement":"There is a Harvard-educated person who has never attended Harvard.","verdict":"FALSE","explanation":"Harvard degrees require completion of a Harvard programme. Online courses offer certificates, but not degrees. However, this is a philosophical question — some argue exceptional honorary degrees blur the line.","category":"language","hook":"True or False?"},
{"id":"tof_0304","statement":"Toilet handles flush the opposite direction in the southern hemisphere.","verdict":"FALSE","explanation":"The Coriolis effect is far too weak to affect a toilet flush. The direction water exits is determined by the toilet's design and jet angles, not which hemisphere you are in.","category":"science","hook":"The hemisphere flush myth"},
{"id":"tof_0305","statement":"You can survive longer without food than without sleep.","verdict":"TRUE","explanation":"Humans can survive weeks or even months without food (with water). Sleep deprivation, however, causes hallucinations and organ failure within 11 days. Rats die from sleep deprivation faster than starvation.","category":"science","hook":"True or False?"},
{"id":"tof_0306","statement":"Jupiter has more moons than any other planet in our solar system.","verdict":"TRUE","explanation":"As of 2024, Jupiter has 95 confirmed moons — the most of any planet in the solar system, far ahead of Saturn's 146 (though Saturn's count recently surpassed Jupiter's in some tallies).","category":"space","hook":"Which planet has the most moons?"},
{"id":"tof_0307","statement":"The word 'quiz' was invented on a bet.","verdict":"TRUE","explanation":"According to legend, Richard Daly bet he could introduce a new word to Dublin overnight in 1791. He allegedly chalked 'QUIZ' on walls all over the city. By morning, people were using it — though historians debate the story's accuracy.","category":"language","hook":"True or False?"},
{"id":"tof_0308","statement":"Sound travels faster through water than through air.","verdict":"TRUE","explanation":"Sound travels about 1,480 m/s through water compared to approximately 343 m/s through air — over four times faster. The denser medium allows sound waves to propagate more efficiently.","category":"science","hook":"Water vs air"},
{"id":"tof_0309","statement":"The human eye can detect a single photon of light in complete darkness.","verdict":"TRUE","explanation":"Research shows that the human eye, particularly the rod photoreceptors, can detect a single quantum of light (one photon) in total darkness. The brain may filter these signals, but the detection occurs.","category":"science","hook":"True or False?"},
{"id":"tof_0310","statement":"There is a country with no official capital city.","verdict":"TRUE","explanation":"Nauru, the world's smallest island nation, has no official capital city. The government offices are in the Yaren district, but it has not been officially designated as a capital.","category":"geography","hook":"Which country has no capital?"},
{"id":"tof_0311","statement":"Metal gets heavier when it rusts.","verdict":"TRUE","explanation":"Rusting is oxidation — iron combining with oxygen from the air to form iron oxide. The added oxygen atoms make the rusted metal measurably heavier than the original metal.","category":"science","hook":"True or False?"},
{"id":"tof_0312","statement":"The Spanish Flu originated in Spain.","verdict":"FALSE","explanation":"The 1918 pandemic was called the Spanish Flu only because Spain, as a neutral country during WWI, had a free press that reported on the epidemic. The actual origin remains debated but is not Spain.","category":"history","hook":"Where did the Spanish Flu start?"},
{"id":"tof_0313","statement":"Walt Disney was cryogenically frozen after his death.","verdict":"FALSE","explanation":"Walt Disney died on 15 December 1966 and was cremated two days later. Cryonics was not yet available and there is no record of any arrangement for it. The myth is completely unfounded.","category":"history","hook":"True or False?"},
{"id":"tof_0314","statement":"A group of porcupines is called a prickle.","verdict":"TRUE","explanation":"The collective noun for porcupines is indeed a prickle, which is fitting given their quills. Other unusual animal group names include a flamboyance of flamingos and a conspiracy of lemurs.","category":"animals","hook":"True or False?"},
{"id":"tof_0315","statement":"Fortune cookies were invented in China.","verdict":"FALSE","explanation":"Fortune cookies were invented in California, likely by Japanese-American bakers in the early 20th century. They are virtually unknown in China, where they are considered an American novelty.","category":"food","hook":"Where are fortune cookies from?"},
{"id":"tof_0316","statement":"The Great Fire of London burned down most of the city in 1666.","verdict":"FALSE","explanation":"The Great Fire of London destroyed around 13,200 houses and 87 churches but killed fewer than 10 people. It left about 100,000 homeless but the 'most of the city' description is an exaggeration.","category":"history","hook":"True or False?"},
{"id":"tof_0317","statement":"Crows can recognise individual human faces.","verdict":"TRUE","explanation":"Research shows crows can remember individual human faces for years and will hold grudges or show gratitude depending on past interactions. They can also teach other crows to recognise specific faces.","category":"animals","hook":"Are crows watching you?"},
{"id":"tof_0318","statement":"The Titanic's full name was RMS Titanic.","verdict":"TRUE","explanation":"RMS stands for Royal Mail Ship — the Titanic was licensed to carry Royal Mail. This designation also meant the ship travelled on a fixed schedule, which contributed to the speed at which it was sailing on its fatal voyage.","category":"history","hook":"True or False?"},
{"id":"tof_0319","statement":"Quicksand is as deadly as movies suggest.","verdict":"FALSE","explanation":"Quicksand is rarely more than a few feet deep. Human density means you float in quicksand up to about waist height. Deaths from quicksand alone are extremely rare — the bigger risk is drowning from a rising tide nearby.","category":"science","hook":"How deadly is quicksand?"},
{"id":"tof_0320","statement":"Oranges are not naturally occurring — they are a hybrid fruit.","verdict":"TRUE","explanation":"Oranges are a hybrid of pomelos and mandarins, created through human cultivation thousands of years ago in Southeast Asia. They do not exist in the wild in their current form.","category":"food","hook":"True or False?"},
{"id":"tof_0321","statement":"Neil Armstrong said 'That's one small step for man' when he landed on the Moon.","verdict":"FALSE","explanation":"Armstrong intended to say 'one small step for a man' — the article 'a' makes the famous contrast meaningful. Audio recordings are unclear on this point, and Armstrong always maintained he said 'a man.'","category":"history","hook":"What did Armstrong actually say?"},
{"id":"tof_0322","statement":"Bamboo is the fastest-growing plant on Earth.","verdict":"TRUE","explanation":"Certain species of bamboo can grow up to 91 cm in a single day — nearly 4 cm per hour. This is visible growth and has been measured under controlled conditions.","category":"nature","hook":"True or False?"},
{"id":"tof_0323","statement":"Finland has more saunas than cars.","verdict":"TRUE","explanation":"Finland has a population of around 5.5 million people, approximately 3.3 million saunas, and about 3.2 million cars. Saunas outnumber cars — and there is roughly one sauna per household.","category":"geography","hook":"How many saunas does Finland have?"},
{"id":"tof_0324","statement":"Mount Everest is in Nepal only.","verdict":"FALSE","explanation":"Mount Everest straddles the border between Nepal and Tibet (China). The summit sits on the border. Both countries claim jurisdiction over the mountain.","category":"geography","hook":"True or False?"},
{"id":"tof_0325","statement":"The human stomach has a new lining every few days.","verdict":"TRUE","explanation":"The stomach's mucous lining is replaced roughly every 3 to 5 days to prevent the stomach from digesting itself with its own acid.","category":"science","hook":"How often does your stomach renew?"},
{"id":"tof_0326","statement":"Catfish have over 100,000 taste buds.","verdict":"TRUE","explanation":"Catfish are extraordinary taste machines. While humans have about 10,000 taste buds mainly on the tongue, catfish have up to 175,000 taste buds covering their entire body surface.","category":"animals","hook":"True or False?"},
{"id":"tof_0327","statement":"The Great Barrier Reef is the world's largest living structure.","verdict":"TRUE","explanation":"The Great Barrier Reef stretches over 2,300 km along Australia's northeast coast and is the world's largest coral reef system and the largest living structure on Earth, visible from space.","category":"nature","hook":"What is the world's largest living structure?"},
{"id":"tof_0328","statement":"Abraham Lincoln was a professional wrestler before becoming president.","verdict":"TRUE","explanation":"Lincoln was an excellent wrestler in his youth, with an official record of 1 loss in around 300 bouts. He was inducted into the National Wrestling Hall of Fame in 1992.","category":"history","hook":"True or False?"},
{"id":"tof_0329","statement":"Koalas have fingerprints almost identical to humans.","verdict":"TRUE","explanation":"Koalas have fingerprints so similar to human fingerprints that they have been known to confuse forensic evidence at crime scenes. They evolved independently from human fingerprints.","category":"animals","hook":"Could a koala frame you for a crime?"},
{"id":"tof_0330","statement":"Scotland's national animal is the unicorn.","verdict":"TRUE","explanation":"The unicorn has been the national animal of Scotland since the 12th century. It was seen as a symbol of power, purity, and independence — qualities valued in the country's heraldic tradition.","category":"geography","hook":"True or False?"},
{"id":"tof_0331","statement":"Glass is not a solid.","verdict":"TRUE","explanation":"Glass is an amorphous solid — sometimes described as a supercooled liquid. Unlike crystalline solids, glass has no ordered molecular structure, placing it in a unique physical category.","category":"science","hook":"Is glass actually a solid?"},
{"id":"tof_0332","statement":"Sharks can develop cancer.","verdict":"TRUE","explanation":"The myth that sharks cannot get cancer has been thoroughly debunked. Multiple shark species have been documented with tumours including malignant cancers.","category":"animals","hook":"True or False?"},
{"id":"tof_0333","statement":"A day on Mercury is longer than a year on Mercury.","verdict":"TRUE","explanation":"Mercury rotates so slowly that one full day (sunrise to sunrise) takes approximately 176 Earth days. But it only takes 88 Earth days to orbit the Sun — so a year passes twice during one day.","category":"space","hook":"Mercury's strange time"},
{"id":"tof_0334","statement":"The longest word in the English language has 189,819 letters.","verdict":"TRUE","explanation":"The chemical name for titin, the largest known protein, contains 189,819 letters if written out in full. It takes over three hours to pronounce and is rarely used or listed in dictionaries.","category":"language","hook":"True or False?"},
{"id":"tof_0335","statement":"Avocados are poisonous to most animals.","verdict":"TRUE","explanation":"Avocados contain persin, a fungicidal toxin that is harmless to humans but toxic to most domestic animals including dogs, cats, rabbits, birds, and horses.","category":"food","hook":"The avocado secret"},
{"id":"tof_0336","statement":"Hair and nails are made of the same protein.","verdict":"TRUE","explanation":"Both hair and nails are made primarily of keratin, a structural protein also found in animal claws, hooves, horns, and reptile scales.","category":"science","hook":"True or False?"},
{"id":"tof_0337","statement":"The smallest country in the world is smaller than most city parks.","verdict":"TRUE","explanation":"Vatican City covers just 0.44 km² — smaller than many golf courses and city parks. It is an independent nation with its own government, military (Swiss Guard), and postal service.","category":"geography","hook":"Just how small is the Vatican?"},
{"id":"tof_0338","statement":"Butterflies taste with their feet.","verdict":"TRUE","explanation":"Butterflies have taste sensors in their feet called chemoreceptors. When they land on a plant, they can immediately detect whether it is suitable to eat or lay eggs on.","category":"animals","hook":"True or False?"},
{"id":"tof_0339","statement":"The Pacific Ocean has more islands than any other ocean.","verdict":"TRUE","explanation":"The Pacific Ocean contains an estimated 25,000 islands — more than all other oceans combined. Many are part of Oceania, Micronesia, Melanesia, and Polynesia.","category":"geography","hook":"Which ocean has the most islands?"},
{"id":"tof_0340","statement":"Some stars you can see at night no longer exist.","verdict":"TRUE","explanation":"Because light takes time to travel, we see stars as they were thousands or millions of years ago. Some visible stars may have already died — we just haven't received the light announcing it yet.","category":"space","hook":"True or False?"},
{"id":"tof_0341","statement":"The word 'terrible' used to mean 'inspiring terror' not 'very bad.'","verdict":"TRUE","explanation":"'Terrible' originally meant awe-inspiring, causing terror in the powerful sense. Ivan the Terrible's Russian title 'Grozny' means 'awe-inspiring' or 'formidable' — not necessarily bad. Language shifted the meaning over centuries.","category":"language","hook":"Words change meaning"},
{"id":"tof_0342","statement":"Sharks are older than trees.","verdict":"TRUE","explanation":"Sharks evolved approximately 450 million years ago. Trees evolved around 360 million years ago, making sharks roughly 90 million years older than trees.","category":"animals","hook":"True or False?"},
{"id":"tof_0343","statement":"Mount Kilimanjaro is the highest free-standing mountain in the world.","verdict":"TRUE","explanation":"Kilimanjaro rises 5,895 metres from the surrounding plains without being part of a mountain range — making it the world's tallest free-standing mountain and Africa's highest peak.","category":"geography","hook":"Africa's giant"},
{"id":"tof_0344","statement":"Eating at night makes you gain more weight than eating the same food during the day.","verdict":"FALSE","explanation":"Weight gain is determined by total caloric intake, not the time of eating. The body processes calories the same way regardless of time. Night eating correlations with weight gain are due to what people tend to eat, not when.","category":"food","hook":"True or False?"},
{"id":"tof_0345","statement":"Humans have a blind spot in their vision.","verdict":"TRUE","explanation":"The point where the optic nerve connects to the retina has no photoreceptors, creating a small blind spot in each eye. The brain fills in this gap using surrounding visual information.","category":"science","hook":"You're partly blind right now"},
{"id":"tof_0346","statement":"The Moon has earthquakes.","verdict":"TRUE","explanation":"The Moon experiences 'moonquakes' caused by gravitational tidal forces from Earth, thermal expansion, and possibly residual tectonic activity. Apollo seismometers recorded moonquakes for years after deployment.","category":"space","hook":"True or False?"},
{"id":"tof_0347","statement":"Pineapple was once so rare it was rented for display at parties.","verdict":"TRUE","explanation":"In 18th-century Britain, pineapples were exotic status symbols costing the equivalent of thousands of pounds. Wealthy hosts would rent a single pineapple to display at parties as a centrepiece.","category":"history","hook":"The most exclusive fruit"},
{"id":"tof_0348","statement":"Russia is larger than Pluto.","verdict":"TRUE","explanation":"Russia covers about 17.1 million km². Pluto's surface area is approximately 17.7 million km² — very similar. Russia is technically slightly smaller, but both are remarkably close in size.","category":"geography","hook":"True or False?"},
{"id":"tof_0349","statement":"Some types of fungus can infect and control the behaviour of insects.","verdict":"TRUE","explanation":"Ophiocordyceps fungi infect ants and other insects, eventually controlling their movement to climb to a high point before the fungus kills the host and releases spores from the highest possible position.","category":"nature","hook":"Real-life zombie fungus"},
{"id":"tof_0350","statement":"Humans are the only primates that walk fully upright on two legs.","verdict":"TRUE","explanation":"While other great apes can walk bipedally for short distances, humans are the only primates that are fully bipedal as their primary mode of locomotion. Our anatomy is uniquely adapted for upright walking.","category":"science","hook":"True or False?"},
{"id":"tof_0351","statement":"A jiffy is shorter than a millisecond.","verdict":"TRUE","explanation":"In physics, a jiffy is defined as the time it takes light to travel one femtometre (10^-15 metres) — approximately 3 × 10^-26 seconds, many orders of magnitude shorter than a millisecond.","category":"science","hook":"How quick is a jiffy?"},
{"id":"tof_0352","statement":"The inventor of the World Wide Web is still alive.","verdict":"TRUE","explanation":"Tim Berners-Lee invented the World Wide Web in 1989 and is still alive, born in 1955. He has continued to advocate for an open, free internet and data privacy rights.","category":"technology","hook":"True or False?"},
{"id":"tof_0353","statement":"Elephants are afraid of mice.","verdict":"FALSE","explanation":"There is no evidence that elephants fear mice. The myth may come from the idea that mice could crawl into an elephant's trunk, but elephants show no consistent fear response to mice in studies.","category":"animals","hook":"Do elephants fear mice?"},
{"id":"tof_0354","statement":"The pound sign # is called an octothorpe.","verdict":"TRUE","explanation":"The # symbol's official name is octothorpe, coined by Bell Laboratories engineers in the 1960s when they were adding it to telephone keypads. 'Octo' refers to the eight points of the symbol.","category":"language","hook":"True or False?"},
]

data.extend(new_items)
FILE.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
print(f"Done. Total items: {len(data)}")
